#include <DiscreteRunCheckpoint.hpp>
#include <DiscreteExpressionFormatting.hpp>
#include <charconv>
#include <chrono>
#include <fstream>
#include <iostream>
#include <iomanip>
namespace {
std::string jsonQuote(std::string_view text){std::string out="\"";for(unsigned char c:text){if(c=='"'||c=='\\'){out+='\\';out+=static_cast<char>(c);}else if(c=='\n')out+="\\n";else if(c=='\r')out+="\\r";else if(c=='\t')out+="\\t";else if(c<32){const char* hex="0123456789abcdef";out+="\\u00";out+=hex[c>>4];out+=hex[c&15];}else out+=static_cast<char>(c);}return out+'"';}
bool resourceFailure(std::exception_ptr failure){try{std::rethrow_exception(failure);}catch(const DiscreteResourceExhausted&){return true;}catch(const std::exception& error){auto nested=dynamic_cast<const std::nested_exception*>(&error);return nested&&resourceFailure(nested->nested_ptr());}catch(...){return false;}}
const char* stopName(DiscreteSearchStop s){switch(s){case DiscreteSearchStop::ExactFit:return "exact_fit";case DiscreteSearchStop::GenerationLimit:return "generation_limit";case DiscreteSearchStop::LossBudget:return "loss_budget";case DiscreteSearchStop::NoViableCandidates:return "no_viable_candidates";case DiscreteSearchStop::Cancelled:return "cancelled";}throw std::logic_error("unknown stop");}
std::int64_t reference(std::string_view kind,std::int64_t n){if(kind=="series")return n*(n+1)/2;std::int64_t answer=1;for(std::int64_t k=1;k<=n;++k)answer*=k;return answer;}
std::uint64_t number(std::string_view t){std::uint64_t n=0;const auto r=std::from_chars(t.data(),t.data()+t.size(),n);if(r.ec!=std::errc{}||r.ptr!=t.data()+t.size())throw std::invalid_argument("unsigned integer argument required");return n;}
}
int main(int argc,char** argv){try{
 std::string kind;std::filesystem::path output;std::uint32_t seed=0;unsigned threads=1;std::optional<std::filesystem::path> resume;
 for(int i=1;i<argc;i+=2){if(i+1==argc)throw std::invalid_argument("missing option value");std::string_view key=argv[i],value=argv[i+1];if(key=="--case")kind=value;else if(key=="--output")output=value;else if(key=="--resume")resume=value;else if(key=="--seed"){auto n=number(value);if(n>UINT32_MAX)throw std::invalid_argument("seed range");seed=static_cast<std::uint32_t>(n);}else if(key=="--threads"){auto n=number(value);if(!n||n>64)throw std::invalid_argument("threads range");threads=static_cast<unsigned>(n);}else throw std::invalid_argument("unknown option");}
 if((kind!="series"&&kind!="factorial")||output.empty())throw std::invalid_argument("--case series|factorial --output PATH [--seed N --threads N --resume FILE]");
 std::filesystem::create_directories(output);DiscreteExpressionLimits expressionLimits;expressionLimits.maxNodes=25;expressionLimits.maxDepth=6;expressionLimits.maxConstants=25;expressionLimits.maxIterationDepth=2;
 DiscreteEvaluationLimits evaluation{200000,200000,1024*1024,64,1024,2};std::vector<DiscreteRegressionRow> rows;const std::int64_t last=kind=="series"?8:6;
 for(std::int64_t n=0;n<=last;++n)rows.push_back({{n},reference(kind,n)});
 auto problem=DiscreteRegressionProblem::create(1,rows,expressionLimits,evaluation);DiscreteSearchConfig config;config.population=64;config.maxGenerations=200;config.maxLossAttempts=10048;
 config.grammar.operators={DiscreteKind::Add,DiscreteKind::Subtract,DiscreteKind::Multiply,DiscreteKind::Sum,DiscreteKind::Product};config.grammar.constants={0,1,2};config.grammar.booleanConstants.clear();config.grammar.iterationBoundsAreTerminals=true;config.grammar.maxIterationNesting=2;
 RandomContext random(seed,ExecutionConfig{threads});std::unique_ptr<DiscreteEvolutionRun> run;auto start=std::chrono::steady_clock::now();
 if(resume)run=DiscreteEvolutionRun::restore(loadDiscreteRunCheckpoint(*resume),problem,config,random);else run=std::make_unique<DiscreteEvolutionRun>(problem,config,random);
 const auto initial=run->population().bestSeen();const auto initialLoss=initial?initial->fitness():-1;const auto initialGeneration=*run->population().generation();std::optional<std::uint64_t> discovery;if(initial&&initial->fitness()==0)discovery=run->population().generation();
 std::string failure,failureKind;
 try{while(!run->stoppingReason()){if(run->step()!=GenerationOutcome::Committed)break;if(run->population().bestSeen()->fitness()==0)discovery=run->population().generation();if(*run->population().generation()%10==0)saveCheckpointSeries(output/"checkpoints",*run->population().generation(),run->checkpoint(),3);}}
 catch(const std::exception& e){failure=e.what();const auto error=std::current_exception();failureKind=resourceFailure(error)?"resource_exhausted":isEvaluationBudget(error)?"loss_budget":isEvaluationCancelled(error)?"cancelled":"operational_failure";}
 // Freeze the representative before any assessment: checkpoint and canonical selected record.
 saveCheckpointSeries(output/"checkpoints",*run->population().generation(),run->checkpoint(),3);const auto best=run->population().bestSeen();if(!best)throw std::runtime_error("no viable selected model");const auto canonical=best->text();
 {std::ofstream frozen(output/"selected.json");frozen<<"{\"canonical\":"<<jsonQuote(canonical)<<",\"loss\":"<<best->fitness()<<",\"generation\":"<<*run->population().generation()<<"}\n";if(!frozen)throw std::runtime_error("selection record I/O failure");}
 const double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();std::size_t assessmentMatches=0,assessmentInvalid=0;std::uint64_t assessmentVisits=0,assessmentIterations=0;std::vector<std::int64_t> predictions;
 const std::int64_t assessmentLast=kind=="series"?12:9;for(std::int64_t n=last+1;n<=assessmentLast;++n){auto prediction=best->expression().evaluate(std::array{n},evaluation);assessmentVisits+=prediction.nodeVisits;assessmentIterations+=prediction.iterations;if(!prediction.valid()){++assessmentInvalid;continue;}predictions.push_back(prediction.value->integer());if(prediction.value->integer()==reference(kind,n))++assessmentMatches;}
 const auto work=run->work();const auto stats=run->algorithm().variation().statistics();const auto stop=run->stoppingReason();std::ofstream result(output/"result.json");result<<std::setprecision(17)<<"{\n\"case\":"<<jsonQuote(kind)<<",\"seed\":"<<seed<<",\"threads\":"<<threads<<",\"resumed\":"<<(resume?"true":"false")<<",\"initial_generation\":"<<initialGeneration<<",\"initial_loss\":"<<initialLoss<<",\"final_loss\":"<<best->fitness()<<",\"canonical\":"<<jsonQuote(canonical)<<",\"pretty\":"<<jsonQuote(formatDiscreteExpression(best->expression()))<<",\"uses_iteration\":"<<(!best->expression().binders().empty()?"true":"false")<<",\"nodes\":"<<best->expression().nodeCount()<<",\"depth\":"<<best->expression().depth()<<",\"constants\":"<<best->expression().constantCount()<<",\"discovery_generation\":"<<(discovery?std::to_string(*discovery):"null")<<",\"generation\":"<<*run->population().generation()<<",\"attempted_generations\":"<<run->algorithm().attempts()<<",\"loss_attempts\":"<<work.lossAttempts<<",\"rows\":"<<work.rowAttempts<<",\"node_visits\":"<<work.nodeVisits<<",\"operations\":"<<work.operations<<",\"iterations\":"<<work.iterations<<",\"iteration_operations\":"<<work.iterationOperations<<",\"invalid_losses\":"<<work.invalidLosses<<",\"mutations\":"<<stats.mutations<<",\"crossovers\":"<<stats.crossovers<<",\"rejections\":"<<stats.rejections<<",\"fallbacks\":"<<stats.fallbacks<<",\"seconds\":"<<seconds<<",\"stop\":"<<jsonQuote(failure.empty()?(stop?stopName(*stop):"no_viable_candidates"):failureKind)<<",\"failure\":"<<jsonQuote(failure)<<",\"assessment_matches\":"<<assessmentMatches<<",\"assessment_rows\":"<<(assessmentLast-last)<<",\"assessment_invalid\":"<<assessmentInvalid<<",\"assessment_visits\":"<<assessmentVisits<<",\"assessment_iterations\":"<<assessmentIterations<<",\"assessment_predictions\":[";for(std::size_t i=0;i<predictions.size();++i){if(i)result<<',';result<<predictions[i];}result<<"]}\n";if(!result)throw std::runtime_error("result record I/O failure");std::cout<<kind<<" seed="<<seed<<" loss="<<best->fitness()<<" generation="<<*run->population().generation()<<" attempts="<<work.lossAttempts<<'\n'<<canonical<<'\n';return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
